<?php	//verifica la autenticacion del usuario	if ($SessionAuthenticated != 'SI') {		DestroySession();		$Session -> Destroy();		$ExitForm = 'index';		header(sprintf('Location: %s', $ExitForm));		exit();	}	//verificamos si el usuario no ha caducado	$Status =   GetValue(					sprintf('SELECT Status FROM CelaUsuario WHERE id = %s;',						GetSQLValueString($SessionUserId, 'int')					),					'Status'				);	if($Status == 2){		DestroySession();		$Session -> Destroy();		$ExitForm = 'index';		header(sprintf('Location: %s', $ExitForm));		exit();	}	/*Se Obtienen los privilegios del rol*/	$RouteForm          = substr(strrchr($_SERVER['PHP_SELF'], '/'), 1);	$PrivilegesGroup    = GetFormPrivileges($RouteForm, $SessionGroupId, 2);	/*Se Obtienen los privilegios del usuario*/	$PrivilegesUser     = GetFormPrivileges($RouteForm, $SessionUserId, 3);	//print_r($PrivilegesGroup);	//print_r($PrivilegesUser);	$Privileges = array_merge($PrivilegesGroup, $PrivilegesUser);	//print_r($Privileges);	if($_GET)		DecodeGet($_SERVER['REQUEST_URI']);	if(isset($_GET['MenuId']) && $_GET['MenuId'] != ''){		$Session -> Update('CelaCurrentMenu', $_GET['MenuId']);		$SessionCurrentMenu = $Session -> Value('CelaCurrentMenu');	}	if(isset($_GET['Action']) && $_GET['Action'] != ''){		$Session -> Update('CelaFormAction', htmlentities($_SERVER['QUERY_STRING']));		$SessionCurrentAction = $Session -> Value('CelaFormAction');	}else{		$Session -> Update('CelaFormAction', '');		$SessionCurrentAction = $Session -> Value('CelaFormAction');	}//	$Logo   =   GetValue(//					sprintf('SELECT Valor FROM CelaConfiguraci_on WHERE Nombre = %s;',//						GetSQLValueString('Logotipo', 'varchar')//					),//					'Valor'//				);	$Logo = $GlobalConfig['Logotipo'];//	$Slogan =   GetValue(//					sprintf('SELECT Valor FROM CelaConfiguraci_on WHERE Nombre = %s;',//						GetSQLValueString('Slogan', 'varchar')//					),//					'Valor'//				);	$Slogan = $GlobalConfig['Slogan'];	/*Argumentos de las secciones*/	$ArgsCelaHead = array(		'HostName'          => $SessionHostName,		'SessionGroupId'    => $SessionGroupId,	);	$ArgsCelaHeadBar = array(		'HostName'      => $SessionHostName,		'SessionGroup'  => $SessionGroup,		'SessionUser'   => $SessionUser,		'SessionUserId' => $SessionUserId	);	$ArgsCelaSideBar = array(		'RouteForm'     => $RouteForm,		'Logo'          => $Logo,		'SessionGroup'  => $SessionGroupId,		'CurrentMenu'   => $SessionCurrentMenu	);	$ArgsCelaAbout = array(		'HostName'  => $SessionHostName,		'Logo'      => $Logo,		'Slogan'    => $Slogan	);	$ArgsCelaLockSession = array(		'HostName'      => $SessionHostName,		'SessionUser'   => $SessionUser	);	$ArgsCelaBreadcrumb = array(		'RouteForm'     => $RouteForm,		'Action'        => (isset($_GET['Action']) && $_GET['Action'] != '' ? $_GET['Action']:'Leer'),		'SessionGroup'  => $SessionGroup,		'HostName'      => $SessionHostName	);	$ArgsCelaFooter = array(		'HostName'  => $SessionHostName	);	$ArgsCelaHeadContent = array(		'Form'      => $RouteForm,		'Action'    => (isset($_GET['Action']) && $_GET['Action'] != '' ? $_GET['Action']:'Leer'),		'FormTitle' => ''	);		$ArgsScript = array();	$RouteForm = str_replace('.php', '', $RouteForm);	/*Se verifica el tiempo de caducidad de la contraseña*/	$LastChange = GetValue(sprintf('SELECT UltimoCambio FROM CelaHistoriaContrase_na WHERE Usuario = %s ORDER BY id DESC LIMIT 0, 1;', GetSQLValueString($SessionUserId, 'int')), 'UltimoCambio');	$ExpirePass = 0;	if(date('Y-m-d') >= date('Y-m-d', strtotime($LastChange . ' +' . $GlobalConfig['depass'] . ' days'))){		$ExpirePass = 1;	}	if( ($UsuarioActivo == 0 || $ExpirePass == 1) && (!(isset($_GET['Activar'])) || $_GET['Activar'] == 0)){		header('Location: CelaUsuario?'. EncodeThis('Action=Activar&Activar=1&Expire=' . $ExpirePass));		$Connection->close();	}?>